use vstd::prelude::*;

verus! {
    /// A pure specification: all elements of the sequence `s` are equal.
    spec fn all_equal(s: Seq<i32>) -> bool {
        forall|i: int, j: int|
            0 <= i < s.len() && 0 <= j < s.len() ==>
                s[i] == s[j]
    }

    /// Returns true iff every element of `v` is identical.
    /// By convention empty and singleton arrays return true.
    fn mall_equal1(v: &[i32]) -> bool
        ensures
            // The boolean result exactly matches our pure spec
            result == all_equal(v.seq()),
    {
        let n = v.len();
        // Trivial cases: empty or single-element
        if n <= 1 {
            // vacuously all_equal for len = 0 or 1
            return true;
        }

        // Remember the first element
        let first = v[0];

        // Scan from 1..n, maintaining that all v[0..i) == first.
        let mut i: usize = 1;
        while i < n
            invariant
                1 <= i && i <= n,
                // All elements before i are equal to `first`
                forall|k: int| 0 <= k < (i as int) ==> v[k as usize] == first,
            decreases n - i,
        {
            if v[i] != first {
                // We have found a genuine mismatch at indices 0 and i.
                // Therefore our spec `all_equal(v.seq())` must be false.
                assert(!all_equal(v.seq())) by {
                    // v[0] != v[i] witnesses the negation of the universal spec
                    assert(v[0] != v[i]);
                }
                return false;
            }
            i += 1;
        }

        // If we reached here, i == n and every v[k] == first for k<n.
        // Hence for any pair (a,b) in-bounds, v[a]==first and v[b]==first,
        // so v[a]==v[b].  That exactly shows all_equal(v.seq()) is true.
        assert(all_equal(v.seq())) by {
            // From the loop invariant at i==n:
            assert(forall|k: int| 0 <= k < (n as int) ==> v[k as usize] == first);
            // Now, for arbitrary a,b in [0,n), v[a]==first and v[b]==first,
            // so v[a]==v[b], i.e. the universal spec holds.
        }
        true
    }
}

fn main() {
    // small smoke‐tests
    let a0: Vec<i32> = vec![];
    let a1: Vec<i32> = vec![42];
    let a2: Vec<i32> = vec![7,7,7];
    let b2: Vec<i32> = vec![1,2,1];

    assert!(mall_equal1(&a0));
    assert!(mall_equal1(&a1));
    assert!(mall_equal1(&a2));
    assert!(!mall_equal1(&b2));
}